import{_ as t,c as s,o,a3 as r}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Timesheets","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/timesheets/timesheets.md","filePath":"master/services/timesheets/timesheets.md","lastUpdated":1791902625000}'),a={name:"master/services/timesheets/timesheets.md"};function n(i,e,l,h,d,m){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="timesheets" tabindex="-1">Timesheets <a class="header-anchor" href="#timesheets" aria-label="Permalink to &quot;Timesheets&quot;">​</a></h1><p>A <strong>timesheet</strong> entry records the time someone spent on a task. Each entry names the date, the employee, the project, the task and the hours. Use timesheets to see where time goes and to compare the time spent on projects and tasks.</p><blockquote><p><strong>In simple words:</strong> A timesheet is a diary of who worked on what, and for how long.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Timesheets need to be turned on for projects.</p><ol><li>Go to <code>Project → Settings → Manage Time</code>.</li><li>Turn on <strong>Enable Timesheets</strong>.</li><li>Save the changes.</li></ol><p>See <a href="./../project/settings.html">Project settings</a> for the full list of project settings.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open <code>Timesheets</code> from the main menu to see all entries in a list. The list shows these columns: <strong>Date</strong>, <strong>Employee</strong>, <strong>Project</strong>, <strong>Task</strong>, <strong>Description</strong> and <strong>Time Spent</strong>. <strong>Created At</strong> and <strong>Updated At</strong> are also available from the column manager.</p><p>Use the toolbar to find entries. See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><ul><li><strong>Group by:</strong> <strong>Date</strong>, <strong>Employee</strong>, <strong>Project</strong>, <strong>Task</strong> or <strong>Creator</strong>.</li><li><strong>Filters:</strong> <strong>Date From</strong>, <strong>Date Until</strong>, <strong>Employee</strong>, <strong>Project</strong>, <strong>Task</strong> and <strong>Creator</strong>.</li></ul><h2 id="add-a-timesheet-entry" tabindex="-1">Add a timesheet entry <a class="header-anchor" href="#add-a-timesheet-entry" aria-label="Permalink to &quot;Add a timesheet entry&quot;">​</a></h2><ol><li><p>Go to <code>Timesheets</code> and click the button to add a new entry.</p></li><li><p>Fill in the form:</p><ul><li><strong><em>Date:</em></strong> The day the work was done. This field is required.</li><li><strong><em>Employee:</em></strong> The person who did the work. This field is required.</li><li><strong><em>Project:</em></strong> The project the work belongs to. This field is required.</li><li><strong><em>Task:</em></strong> The task the work belongs to. This field is required.</li><li><strong><em>Description:</em></strong> A short note on what was done.</li><li><strong><em>Time Spent:</em></strong> The time in hours. This field is required. For example, <code>1.5</code> means 1 hour 30 minutes.</li></ul></li><li><p>Save the entry.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also add time from a task. Open the task and use its <strong>Timesheets</strong> tab. See <a href="./../project/tasks.html">Tasks</a>.</p></div><h2 id="edit-or-delete-an-entry" tabindex="-1">Edit or delete an entry <a class="header-anchor" href="#edit-or-delete-an-entry" aria-label="Permalink to &quot;Edit or delete an entry&quot;">​</a></h2><p>On the list, use the actions at the end of a row to edit or delete an entry. To delete several entries at once, tick them and use the bulk delete action.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../project/tasks.html">Tasks</a></li><li><a href="./../project/settings.html">Project settings</a></li></ul>',18)]))}const p=t(a,[["render",n]]);export{c as __pageData,p as default};
